<?php
namespace App\Http\Controllers; use App\Models\{EmployeeTrainingCredential,TrainingSession}; use App\Services\TrainingCertificateService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class TrainingCertificateController extends Controller{public function generate(TrainingSession$session,Request$r,TrainingCertificateService$s){abort_unless($session->company_id===$r->user()->company_id,403);$d=$r->validate(['employee_id'=>'required|exists:empleados,id','credential_type'=>'required|in:attendance_certificate,internal_approval_certificate']);$credential=$s->generate($session,$d['employee_id'],$d['credential_type'],$r->user()->id);return redirect()->route('training.credentials.download',$credential);}public function download(EmployeeTrainingCredential$credential,Request$r){abort_unless($credential->company_id===$r->user()->company_id,403);return Storage::disk(config('training.evidence_disk','local'))->download($credential->document_path);}}
